import { readFileSync, writeFileSync } from 'node:fs';

const file = process.argv[2];
const out = process.argv[3];
const src = readFileSync(file, 'utf8');

const results = [];
let idx = 0;
while ((idx = src.indexOf('test.for(', idx)) !== -1) {
  let i = src.indexOf('[', idx);
  // bracket-match, skipping string/template/comment content
  let depth = 0, j = i, inStr = null, esc = false;
  for (; j < src.length; j++) {
    const c = src[j];
    if (inStr) {
      if (esc) { esc = false; continue; }
      if (c === '\\') { esc = true; continue; }
      if (c === inStr) inStr = null;
      continue;
    }
    if (c === '"' || c === "'" || c === '`') { inStr = c; continue; }
    if (c === '[') depth++;
    else if (c === ']') { depth--; if (depth === 0) break; }
  }
  const literal = src.slice(i, j + 1);
  results.push(eval(`(${literal})`));
  idx = j;
}
writeFileSync(out, JSON.stringify(results, null, 1));
console.log(file, '->', results.map(r => r.length).join(', '));
EOF
cd /tmp/extract && for f in /workspace/tests/javascript/*/*.test.ts; do node extract.mjs "$f" "/tmp/extract/$(basename $f .test.ts).json"; done

