import pytest

from gbnf import GBNF{extra_imports}

'''


def lit(value, indent=4):
    """Render a JSON-derived value as a Python literal."""
    pad = ' ' * indent
    if isinstance(value, list):
        if not value:
            return '[]'
        inner = ',\n'.join(pad + '    ' + lit(v, indent + 4) for v in value)
        return '[\n' + inner + ',\n' + pad + ']'
    if isinstance(value, dict):
        items = ', '.join(f'{k!r}: {lit(v, indent)}' for k, v in value.items())
        return '{' + items + '}'
    if isinstance(value, bool) or value is None:
        return repr(value)
    return repr(value)


def table(rows, indent=0):
    pad = ' ' * indent
    return '[\n' + ',\n'.join(pad + '    ' + lit(row, indent + 4) for row in rows) + ',\n' + pad + ']'


def load(name):
    with open(f'/tmp/extract/{name}.json') as f:
        return json.load(f)


def write(path, body):
    full = os.path.join(OUT, path)
