import { readFileSync, writeFileSync } from 'node:fs';
import mod from '/tmp/jsref/src/index.ts';
import * as all from '/tmp/jsref/src/index.ts';

const GBNF = all.default ?? mod;
const { GrammarParseError, InputParseError } = all;

const load = (n) => JSON.parse(readFileSync(`/tmp/extract/${n}.json`, 'utf8'));
const results = {};
let failures = 0;
const check = (label, actual, expected) => {
  const a = JSON.stringify(actual), e = JSON.stringify(expected);
  if (a !== e) { failures++; console.log('MISMATCH', label, '\n  actual  ', a, '\n  expected', e); }
};

// validate-grammar
{
  const [valid, invalid] = load('validate-grammar');
  for (const g of valid) { if (!GBNF(g)) { failures++; console.log('MISMATCH valid grammar', g); } }
  for (const [g, pos, reason] of invalid) {
    let msg = null;
    try { GBNF(g); } catch (err) { msg = err.message; }
    check(`invalid grammar ${JSON.stringify(g)}`, msg, new GrammarParseError(g, pos, reason).message);
  }
}
// validate-input
{
  const [valid, invalid] = load('validate-input');
  for (const [g, i] of valid) { if (!GBNF(g, i)) { failures++; console.log('MISMATCH valid input', g, i); } }
  for (const [g, i, pos] of invalid) {
    let msg = null;
    try { GBNF(g).add(i); } catch (err) { msg = err.message; }
    check(`invalid input ${JSON.stringify([g, i])}`, msg, new InputParseError(i, pos, '').message);
  }
}
// iteration
{
  const [cases] = load('iteration');
  for (const [g, expected] of cases) check(`iteration ${JSON.stringify(g)}`, [...GBNF(g)], expected);
}
// iteration with an initial string
{
  const [cases] = load('iteration-with-an-initial-string');
  for (const [g, input, expected] of cases)
    check(`initial ${JSON.stringify([g, input])}`, [...GBNF(g).add(input)], expected);
}
// iteration with additional strings
{
  const [throwing, passing] = load('iteration-with-additional-strings');
  for (const [g, start, add] of throwing) {
    let threw = false;
    try { GBNF(g, start).add(add); } catch { threw = true; }
    check(`throwing ${JSON.stringify([g, start, add])}`, threw, true);
  }
  for (const [g, start, add, expected] of passing)
    check(`passing ${JSON.stringify([g, start, add])}`, [...GBNF(g, start).add(add)], expected);
}
// grammars
{
  const unescape = (s) => s.replace(/\\n/g, '\n').replace(/\\t/g, '\t');
  const [cases] = load('grammars');
  for (const [name, tc, g] of cases) {
    try {
      let state = GBNF(unescape(g));
      for (const ch of unescape(tc)) state = state.add(ch);
    } catch (err) { failures++; console.log('MISMATCH grammar', name, JSON.stringify(tc), err.message.split('\n')[0]); }
  }
}
console.log(failures === 0 ? 'REFERENCE: all extracted expectations match' : `REFERENCE: ${failures} mismatches`);

