import { readFileSync, writeFileSync } from 'node:fs';
import * as all from '/tmp/jsref/src/index.ts';

const GBNF = all.default;
const load = (n) => JSON.parse(readFileSync(`/tmp/extract/${n}.json`, 'utf8'));
const unescape = (s) => s.replace(/\\n/g, '\n').replace(/\\t/g, '\t');

// every distinct grammar mentioned anywhere in the suite
const grammars = new Set();
for (const [, invalid] of [load('validate-grammar')]) for (const [g] of invalid) grammars.add(g);
for (const g of load('validate-grammar')[0]) grammars.add(g);
for (const [g] of load('validate-input')[1]) grammars.add(g);
for (const [g] of load('iteration')[0]) grammars.add(g);
for (const [g] of load('iteration-with-an-initial-string')[0]) grammars.add(g);
for (const [g] of load('iteration-with-additional-strings')[1]) grammars.add(g);
for (const [, , g] of load('grammars')[0]) grammars.add(unescape(g));

// deterministic PRNG so the Python side replays the identical inputs
let seed = 20240917;
const rand = () => {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed / 0x7fffffff;
};
const ALPHABET = [...'abcxyzABZ019 \t\n+-*/=()[]{}",:._\\|^?'];

const cases = [];
for (const grammar of grammars) {
  // an alphabet biased toward characters the grammar actually mentions
  const pool = [...new Set([...ALPHABET, ...grammar.replace(/[a-z-]{2,}/g, '')])];
  for (let trial = 0; trial < 12; trial++) {
    const len = 1 + Math.floor(rand() * 14);
    let input = '';
    for (let i = 0; i < len; i++) input += pool[Math.floor(rand() * pool.length)];
    cases.push([grammar, input]);
  }
}

const observe = (grammar, input) => {
  const steps = [];
  let state;
  try {
    state = GBNF(grammar);
  } catch (err) {
    return { init: err.constructor.name + '|' + err.message, steps };
  }
  steps.push(JSON.stringify([...state]));
  for (const ch of input) {
    try {
      state = state.add(ch);
      steps.push(JSON.stringify([...state]));
    } catch (err) {
      steps.push(err.constructor.name + '|' + err.message);
      break;
    }
  }
  return { init: null, steps };
};

const out = cases.map(([g, i]) => ({ grammar: g, input: i, ...observe(g, i) }));
writeFileSync('/tmp/extract/fuzz-expected.json', JSON.stringify(out));
console.log('generated', out.length, 'differential cases');

