cd /workspace/ported_implementation && python3 - <<'PY'
import json, sys
sys.path.insert(0, '.')
from gbnf import GBNF

cases = json.load(open('/tmp/extract/fuzz-expected.json'))

def dumps(rules):
    return json.dumps(rules, separators=(',', ':'))

def observe(grammar, input_):
    steps = []
    try:
        state = GBNF(grammar)
    except Exception as err:
        return {'init': type(err).__name__ + '|' + str(err), 'steps': steps}
    steps.append(dumps([r.as_dict() for r in state]))
    for ch in input_:
        try:
            state = state.add(ch)
            steps.append(dumps([r.as_dict() for r in state]))
        except Exception as err:
            steps.append(type(err).__name__ + '|' + str(err))
            break
    return {'init': None, 'steps': steps}

mismatches = 0
for case in cases:
    got = observe(case['grammar'], case['input'])
    if got['init'] != case['init'] or got['steps'] != case['steps']:
        mismatches += 1
        if mismatches <= 5:
            print('MISMATCH', repr(case['grammar'])[:70], repr(case['input']))
            print('  ref:', json.dumps(case)[:300])
            print('  got:', json.dumps(got)[:300])
print(f'{len(cases)} differential cases, {mismatches} mismatches')
PY
